export const getListGroupMessagesUrl = (
  id: number,
  params?: ListGroupMessagesParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/groups/${id}/messages?${stringifiedParams}`
    : `/api/groups/${id}/messages`;
};

export const listGroupMessages = async (
  id: number,
  params?: ListGroupMessagesParams,
  options?: RequestInit,
): Promise<GroupMessage[]> => {
  return customFetch<GroupMessage[]>(getListGroupMessagesUrl(id, params), {
    ...options,
    method: "GET",
  });
};

